import json
import pandas as pd

missing = []
conversions = []

# Cargar tabla
try:
    df = load_table("02a227cb112d2d4c-t01")
except Exception as e:
    missing.append({"subquestion_id": "q1", "reason": f"No se pudo cargar la tabla 02a227cb112d2d4c-t01: {str(e)}"})
    df = pd.DataFrame()

results = []

if not df.empty:
    # Verificar que existan las filas necesarias
    if not all(x in df['Concepto'].values for x in ['Gasto en ciencia y tecnología', 'Gastos totales']):
        missing.append({"subquestion_id": "q1", "reason": "Faltan filas necesarias en la tabla para calcular la proporción del gasto en ciencia y tecnología respecto al gasto total."})
    else:
        # Extraer las filas
        gasto_ciencia = df.loc[df['Concepto'] == 'Gasto en ciencia y tecnología'].iloc[0]
        gasto_total = df.loc[df['Concepto'] == 'Gastos totales'].iloc[0]

        # Calcular proporción para cada año
        proporciones = []
        for year in ['2019', '2020', '2021', '2022', '2023']:
            val_gasto_ciencia = gasto_ciencia[year]
            val_gasto_total = gasto_total[year]
            if pd.isna(val_gasto_ciencia) or pd.isna(val_gasto_total) or val_gasto_total == 0:
                missing.append({"subquestion_id": "q1", "reason": f"Dato faltante o cero para el año {year} en gasto en ciencia o gasto total."})
            else:
                proporcion = (val_gasto_ciencia / val_gasto_total) * 100
                proporciones.append({"label": year, "value": float(proporcion)})

        if proporciones:
            results.append({
                "subquestion_id": "q1",
                "value": proporciones,
                "unit": "%",
                "label": "Proporción del gasto en ciencia y tecnología respecto al gasto total por año"
            })
else:
    missing.append({"subquestion_id": "q1", "reason": "La tabla está vacía."})

print(json.dumps({"results": results, "missing": missing, "conversions": conversions}, ensure_ascii=False))

